function activeDatasetSource(){return activeTrainTab==='casting_holes'?'casting_holes':'container_detector'}
function populateTrainingCheckpoints(){const mode=$('initMode').value,src=activeDatasetSource(),eligible=checkpointRows.filter(c=>c.downloadAllowed&&(!c.datasetSource||c.datasetSource===src)&&(mode==='resume'?c.resumeAllowed:c.fineTuneAllowed));const select=$('checkpointSelect'),old=select.value;select.replaceChildren();eligible.forEach(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=`${c.name}${c.resumeAllowed?' · resume ready':''}`;select.append(o)});if(old&&eligible.some(c=>c.id===old))select.value=old;if(!eligible.length){const o=document.createElement('option');o.value='';o.textContent=mode==='resume'?'No interrupted last.pt checkpoints':'Upload or finish a training run first';select.append(o)}}
