function formatCheckpointDate(value){if(!value)return'Not recorded';const date=new Date(value);return Number.isNaN(date.getTime())?'Not recorded':date.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}
function appendDetail(parent,label,value,fullValue){const item=document.createElement('div');item.className='run-detail';const term=document.createElement('span');term.textContent=label;const detail=document.createElement('strong');detail.textContent=value||'Not recorded';if(fullValue)detail.title=fullValue;item.append(term,detail);parent.append(item)}
function makeDownloadLink(checkpoint){const link=document.createElement('a');link.className='button ghost checkpoint-download';link.textContent='Download .pt';if(checkpoint.downloadAllowed){link.href=checkpoint.downloadUrl;link.setAttribute('download',checkpoint.filename||'checkpoint.pt')}else{link.setAttribute('aria-disabled','true');link.title='This checkpoint may still be changing during training.'}return link}
function renderCheckpoint(run,checkpoint){const row=document.createElement('article');row.className='checkpoint-item';const heading=document.createElement('div');heading.className='checkpoint-item-heading';const title=document.createElement('div');title.className='checkpoint-title';const name=document.createElement('strong');name.textContent=checkpoint.filename||`${checkpoint.kind}.pt`;name.title=checkpoint.kind==='best'?'Best validation checkpoint':'Most recent training checkpoint';const kind=document.createElement('span');kind.className=`checkpoint-kind ${checkpoint.kind}`;kind.textContent=checkpoint.kind==='best'?'BEST':'LAST';title.append(name,kind);heading.append(title);if(checkpoint.interim){const interim=document.createElement('span');interim.className='checkpoint-tag interim';interim.textContent='INTERIM CHECKPOINT';interim.title='Training can update this file as epochs progress.';heading.append(interim)}else if(checkpoint.readyForDetection){const ready=document.createElement('span');ready.className='checkpoint-tag ready';ready.textContent='READY FOR DETECTION';heading.append(ready)}const meta=document.createElement('p');meta.className='checkpoint-meta';const size=(Number(checkpoint.sizeBytes||0)/1024/1024).toFixed(1);meta.textContent=`${size} MB · epoch ${checkpoint.epoch??'not recorded'} · updated ${formatCheckpointDate(checkpoint.lastModifiedAt)}${checkpoint.inheritedCheckpointAt?` · inherited checkpoint was ${formatCheckpointDate(checkpoint.inheritedCheckpointAt)}`:''}`;meta.title=checkpoint.description||'';const actions=document.createElement('div');actions.className='model-actions';actions.append(makeDownloadLink(checkpoint));row.append(heading,meta,actions);return row}
function renderRun(run,index){const card=document.createElement('article');card.className=`training-run-card${index===0?' newest':''}`;const head=document.createElement('div');head.className='training-run-head';const titlebox=document.createElement('div');titlebox.className='training-run-title';const title=document.createElement('h4');const localRunDate=run.startedAt?new Date(run.startedAt):null;const baseName=run.baseModel||'YOLO26n';title.textContent=localRunDate&&!Number.isNaN(localRunDate.getTime())?`${baseName} Training — ${localRunDate.toLocaleString(undefined,{month:'short',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}`:(run.name||`Training run · ${run.shortId||''}`);const id=document.createElement('small');id.textContent=`Run ${run.shortId||run.id}`;id.title=run.id||'';titlebox.append(title,id);const badge=document.createElement('span');badge.className=`run-status ${String(run.statusLabel||run.status||'failed').toLowerCase()}`;badge.textContent=run.statusLabel||String(run.status||'failed').toUpperCase();head.append(titlebox,badge);if(run.statusLabel==='TRAINING'){const progress=document.createElement('div');progress.className='run-progress';const progressLabel=document.createElement('div');progressLabel.className='run-progress-label';const text=document.createElement('span');text.textContent=run.stale?'No status update for over two minutes':run.status==='evaluating'?'Final test evaluation':'Training progress';const epoch=document.createElement('strong');epoch.textContent=`${Number(run.epoch)||0} / ${Number(run.totalEpochs)||0} epochs`;progressLabel.append(text,epoch);const bar=document.createElement('progress');bar.max=Math.max(1,Number(run.totalEpochs)||1);bar.value=Math.min(bar.max,Number(run.epoch)||0);progress.append(progressLabel,bar);card.append(head,progress);const warning=document.createElement('p');warning.className='interim-warning';warning.textContent='This run is active. Checkpoint files can change while training progresses, so downloads are disabled until the run stops.';card.append(warning)}else card.append(head);const details=document.createElement('div');details.className='run-details';appendDetail(details,run.startedAt?'Started':'Queued',formatCheckpointDate(run.startedAt||run.createdAt),run.startedAt||run.createdAt);appendDetail(details,run.completedAt?'Completed':'Finished',formatCheckpointDate(run.completedAt||run.finishedAt),run.completedAt||run.finishedAt);appendDetail(details,'Last checkpoint update',formatCheckpointDate(run.lastCheckpointUpdatedAt),run.lastCheckpointUpdatedAt);appendDetail(details,'Elapsed',run.elapsedSeconds==null?'Not recorded':formatDuration(run.elapsedSeconds));appendDetail(details,'Last progress update',formatCheckpointDate(run.updatedAt),run.updatedAt);if(run.estimatedRemainingSeconds!=null&&run.statusLabel==='TRAINING')appendDetail(details,'Estimated remaining',formatDuration(run.estimatedRemainingSeconds));if(run.bestEpoch)appendDetail(details,'Best epoch',String(run.bestEpoch));appendDetail(details,'Checkpoint lineage',run.checkpointLineage&&run.checkpointLineage.resumedFrom?`Resumed from ${run.checkpointLineage.resumedFrom}`:'New run');if(run.resumedBy)appendDetail(details,'Resumed by run',run.resumedBy.slice(0,8),run.resumedBy);if(run.resources&&run.resources.cpuPercent!=null)appendDetail(details,'System CPU',`${run.resources.cpuPercent}%`,'System-wide /proc CPU sample');if(run.resources&&run.resources.processCpuPercent!=null)appendDetail(details,'Training process CPU',`${run.resources.processCpuPercent}%`,'Application process CPU since the previous sample; this may include non-training app work.');if(run.resources&&run.resources.memoryUsedBytes!=null)appendDetail(details,'Memory used',`${(run.resources.memoryUsedBytes/1024**3).toFixed(1)} / ${(run.resources.memoryTotalBytes/1024**3).toFixed(1)} GB`,run.resources.memoryScope||'Memory visible in the container');card.append(details);if(run.message&&['FAILED','CANCELLED'].includes(run.statusLabel)){const message=document.createElement('p');message.className='run-message';message.textContent=run.message;card.append(message)}if(run.checkpoints&&run.checkpoints.length){const list=document.createElement('div');list.className='run-checkpoints';run.checkpoints.forEach(checkpoint=>list.append(renderCheckpoint(run,checkpoint)));card.append(list)}else{const empty=document.createElement('p');empty.className='muted small';empty.textContent='No checkpoint files were saved for this run.';card.append(empty)}const compareLabel=document.createElement('label');compareLabel.className='compare-run';const compare=document.createElement('input');compare.type='checkbox';compare.dataset.compareRun=run.id;compare.checked=selectedComparison.has(run.id);compare.onchange=()=>{if(compare.checked)selectedComparison.add(run.id);else selectedComparison.delete(run.id);renderComparison()};compareLabel.append(compare,document.createTextNode(' Compare'));card.append(compareLabel);const disclosure=document.createElement('details');disclosure.className='run-secondary';const summary=document.createElement('summary');summary.textContent='Experiment details, metrics & logs';const content=document.createElement('div');content.className='experiment-content';content.innerHTML='<p class="muted small">Loading persisted experiment details…</p>';disclosure.append(summary,content);disclosure.addEventListener('toggle',()=>{if(disclosure.open&&!disclosure.dataset.loaded){disclosure.dataset.loaded='true';loadRunDetails(run,content)}});card.append(disclosure);return card}
function formatDuration(seconds){const n=Math.max(0,Number(seconds)||0),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=Math.floor(n%60);return h?`${h}h ${m}m`:`${m}m ${s}s`}
const selectedComparison=new Set();function renderComparison(){const box=$('runComparison'),runs=trainingRuns.filter(r=>selectedComparison.has(r.id));box.replaceChildren();box.hidden=runs.length<2;if(runs.length<2)return;const title=document.createElement('h4');title.textContent='Run comparison';box.append(title);const table=document.createElement('table');table.innerHTML='<thead><tr><th>Run</th><th>Status</th><th>Epoch</th><th>Best epoch</th><th>Config</th><th>mAP50</th><th>mAP50–95</th><th>Test mAP50–95</th><th>Elapsed</th><th>Dataset</th><th>Checkpoints</th></tr></thead>';const body=document.createElement('tbody');runs.forEach(run=>{const row=document.createElement('tr');const summaryMetrics=Object.keys(run.bestMetrics||{}).length?run.bestMetrics:(run.latestMetrics||{});const values=[run.name||run.shortId,run.statusLabel,`${run.epoch||0}/${run.totalEpochs||0}`,run.bestEpoch??'—',configSummary(run.config),metricValue(summaryMetrics,'metrics/mAP50(B)'),metricValue(summaryMetrics,'metrics/mAP50-95(B)'),metricValue(run.testMetrics,'metrics/mAP50-95(B)'),run.elapsedSeconds==null?'—':formatDuration(run.elapsedSeconds),run.datasetFingerprint?run.datasetFingerprint.slice(0,10):'—',run.checkpoints.reduce((sum,c)=>sum+(Number(c.sizeBytes)||0),0)?`${(run.checkpoints.reduce((sum,c)=>sum+(Number(c.sizeBytes)||0),0)/1024**2).toFixed(1)} MB`:'—'];values.forEach(value=>{const cell=document.createElement('td');cell.textContent=value;row.append(cell)});body.append(row)});table.append(body);box.append(table)}
function configSummary(config){if(!config||!Object.keys(config).length)return'Config unavailable';const value=(...keys)=>{for(const key of keys){if(config[key]!==undefined&&config[key]!==null)return config[key]}return'—'};return`${value('imgsz','imageSize')}px · batch ${value('batch')} · ${value('optimizer')} · lr ${value('lr0')} · wd ${value('weight_decay')} · patience ${value('patience')} · seed ${value('seed')}`}
function metricValue(metrics,key){const value=Number(metrics&&metrics[key]);return Number.isFinite(value)?`${(value*100).toFixed(1)}%`:'—'}
async function loadRunDetails(run,root){try{const [job,history,logs]=await Promise.all([api('/api/training/'+run.id),api('/api/training/'+run.id+'/metrics'),api('/api/training/'+run.id+'/logs')]);root.replaceChildren();const metrics=history.metrics||job.epochMetrics||[];const best=job.bestMetrics||{};const summary=document.createElement('p');summary.className='small muted';summary.textContent=`${metrics.length} persisted epochs · dataset ${job.datasetFingerprint||'fingerprint not recorded'}`;root.append(summary);if(job.stale){const stale=document.createElement('p');stale.className='interim-warning';stale.textContent='The job record has not changed recently. This is a stale-progress warning only; the app does not infer that training has failed.';root.append(stale)}const charts=document.createElement('div');charts.className='experiment-charts';[['Losses',['train/box_loss','train/cls_loss','train/dfl_loss','val/box_loss','val/cls_loss','val/dfl_loss']],['Detection quality',['metrics/precision(B)','metrics/recall(B)','metrics/mAP50(B)','metrics/mAP50-95(B)']],['Learning rates',[...new Set(metrics.flatMap(point=>Object.keys(point.metrics||{})))].filter(key=>/^lr\/pg\d+$/.test(key)).sort((a,b)=>Number(a.match(/\d+$/)[0])-Number(b.match(/\d+$/)[0]))]].forEach(([name,keys])=>{const panel=document.createElement('section');panel.className='chart-panel';const heading=document.createElement('h5');heading.textContent=name;const canvas=document.createElement('canvas');canvas.width=700;canvas.height=180;canvas.setAttribute('aria-label',`${name} by epoch`);panel.append(heading,canvas);drawMetricChart(canvas,metrics,keys);charts.append(panel)});root.append(charts);const bestLine=document.createElement('p');bestLine.className='small';bestLine.textContent=Object.keys(best).length?`Best checkpoint metrics: ${Object.entries(best).filter(([k,v])=>k.startsWith('metrics/')&&Number.isFinite(Number(v))).map(([k,v])=>`${k.replace('metrics/','')}: ${(Number(v)*100).toFixed(1)}%`).join(' · ')}${job.bestEpoch?` · best epoch ${job.bestEpoch}`:''}${job.selectionMetric?` · selected by ${job.selectionMetric.name}`:''}${job.selectionMetric?` · selection value ${job.selectionMetric.value}`:''}${Object.keys(job.testMetrics||{}).length?` · held-out test: ${Object.entries(job.testMetrics).filter(([k,v])=>k.toLowerCase().includes('map')&&Number.isFinite(Number(v))).map(([k,v])=>`${k.replace('metrics/','')}: ${(Number(v)*100).toFixed(1)}%`).join(' / ')}`:''}`:'Best checkpoint metrics not recorded.';root.append(bestLine);const qualityRows=document.createElement('div');qualityRows.className='metric-rows';const appendMetricSet=(label,values,filter)=>Object.entries(values||{}).filter(([key,value])=>filter(key)&&Number.isFinite(Number(value))).forEach(([key,value])=>{const pill=document.createElement('span');pill.className='metric-pill';pill.textContent=`${label} ${key.replace('metrics/','').replace('test/','').replace('val/','val ').replace('train/','train ').replace('metrics/','').replace('(B)','')}`;const strong=document.createElement('strong');strong.textContent=key.toLowerCase().includes('loss')?Number(value).toFixed(4):`${(Number(value)*100).toFixed(1)}%`;pill.append(strong);qualityRows.append(pill)});appendMetricSet('Best',best,key=>key.startsWith('metrics/')||key.startsWith('val/'));appendMetricSet('Latest',job.metrics,key=>key.startsWith('metrics/')||key.startsWith('val/'));appendMetricSet('Test',job.testMetrics,key=>true);root.append(qualityRows);const metadata=document.createElement('details');metadata.className='run-secondary';const metadataSummary=document.createElement('summary');metadataSummary.textContent='Configuration, environment & dataset diagnostics';metadata.append(metadataSummary);const pre=document.createElement('pre');pre.textContent=JSON.stringify({config:job.config||'Unavailable for this historical run',environment:job.environment||'Unavailable for this historical run',datasetDiagnostics:job.datasetDiagnostics||'Unavailable for this historical run',resources:job.resources||{},averageEpochDurationSeconds:job.averageEpochDurationSeconds??'Not recorded',recentTrainingSpeed:job.recentTrainingSpeed||'Not recorded',estimatedRemainingSeconds:job.estimatedRemainingSeconds??'Not recorded',selectionMetric:job.selectionMetric||'Not recorded',inheritedCheckpoint:job.inheritedCheckpoint||'Not recorded',checkpointLineage:job.checkpointLineage||job.parentRunId||job.resumedFromJobId||'None recorded',bestFitness:job.bestFitness??'Not recorded',optimizer:job.optimizer||'Not recorded'},null,2);metadata.append(pre);root.append(metadata);const logBlock=document.createElement('details');logBlock.className='run-secondary';const logSummary=document.createElement('summary');logSummary.textContent='Run events & logs';logBlock.append(logSummary);const eventList=document.createElement('pre');eventList.textContent=JSON.stringify({events:logs.events||[],failureReason:logs.failureReason||job.failureReason||null,files:logs.files||[]},null,2);logBlock.append(eventList);root.append(logBlock)}catch(error){root.replaceChildren();const message=document.createElement('p');message.className='run-message';message.textContent=`Could not load experiment details: ${error.message}`;root.append(message)}}
function drawMetricChart(canvas,points,keys,scale={}){const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=26;ctx.clearRect(0,0,w,h);ctx.font='12px sans-serif';ctx.fillStyle='#9ba99d';if(!points.length){ctx.fillText('No epoch metrics recorded',pad,h/2);return}const present=keys.filter(key=>points.some(point=>Number.isFinite(Number(point.metrics&&point.metrics[key]))));if(!present.length){ctx.fillText('Metrics unavailable',pad,h/2);return}const vals=points.flatMap(point=>present.map(key=>Number(point.metrics&&point.metrics[key])).filter(Number.isFinite)),min=Number.isFinite(scale.min)?scale.min:Math.min(...vals),max=Number.isFinite(scale.max)?scale.max:Math.max(...vals),span=max-min||1;ctx.strokeStyle='#344438';ctx.beginPath();ctx.moveTo(pad,pad);ctx.lineTo(pad,h-pad);ctx.lineTo(w-pad,h-pad);ctx.stroke();ctx.fillText('epoch 1',pad,h-5);ctx.fillText(`epoch ${points[points.length-1].epoch}`,w-pad-68,h-5);const colors=['#c8f36b','#77d5c0','#b49bff','#f6c873','#ff897e','#8dbbff'];present.forEach((key,index)=>{ctx.strokeStyle=colors[index%colors.length];ctx.lineWidth=2;ctx.beginPath();let begun=false;points.forEach((point,i)=>{const value=Number(point.metrics&&point.metrics[key]);if(!Number.isFinite(value))return;const x=pad+(w-2*pad)*(i/Math.max(1,points.length-1)),y=h-pad-(value-min)/span*(h-2*pad);if(!begun){ctx.moveTo(x,y);begun=true}else ctx.lineTo(x,y)});ctx.stroke();ctx.fillStyle=colors[index%colors.length];ctx.fillText(key.replace('metrics/','').replace('(B)','').replace('train/','tr ').replace('val/','val ').replace('lr/','lr '),pad+(index%3)*210,14+Math.floor(index/3)*12)})}

function renderUploadedCheckpoints(root){const uploaded=checkpointRows.filter(c=>c.kind==='uploaded');if(!uploaded.length||modelRunFilter!=='all')return;const section=document.createElement('section');section.className='uploaded-checkpoint-section';const title=document.createElement('h4');title.textContent='Uploaded checkpoints';section.append(title);uploaded.forEach(c=>{const row=document.createElement('article');row.className='checkpoint-item uploaded-checkpoint';const left=document.createElement('div');left.className='checkpoint-title';const name=document.createElement('strong');name.textContent=c.name||c.filename;const meta=document.createElement('small');meta.textContent=`${(Number(c.sizeBytes||0)/1024/1024).toFixed(1)} MB · uploaded ${formatCheckpointDate(c.createdAt)}`;left.append(name,meta);row.append(left,makeDownloadLink(c));section.append(row)});root.append(section)}
